// Base VTable: [f1 address], [f2 address]
class Base {
public:
    // Vtable slot 0
    virtual void f1() {}
    // Vtable slot 1
    virtual void f2() {}
};

// Derived VTable: [Derived::f1 address], [Base::f2 address]
class Derived : public Base {
public:
    // Overrides slot 0 in Derived's VTable
    void f1() override {}
    // f2 is inherited (slot 1 points to Base::f2)
};

// Object Instantiation (vptr created inside 'p')
Base* p = new Derived();

// Runtime Look-up via Vptr:
// vptr points to Derived's Vtable
p->f1(); // Calls Derived::f1 (vtable[0])
p->f2(); // Calls Base::f2 (vtable[1])
